<?php require '../config/auth.php';login_required('student');$page_title='Notifications';$pdo->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?')->execute([$_SESSION['user_id']]);$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC');$q->execute([$_SESSION['user_id']]);$ns=$q->fetchAll();require '../config/header.php';?><div class="head"><div><h1>Notifications</h1><p>Placement and application updates.</p></div></div><div class="grid"><?php foreach($ns as $n):?><div class="card"><b>🔔 <?=e($n['title'])?></b><p class="muted"><?=nl2br(e($n['message']))?></p><small class="muted"><?=e($n['created_at'])?></small></div><?php endforeach;?></div><?php if(!$ns):?><div class="card empty">No notifications yet.</div><?php endif;?><?php require '../config/footer.php';?>
